import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';
import { FiPlus, FiEdit2, FiTrash2 } from 'react-icons/fi';
import api from '../../services/api';
import { getImageUrl } from '../../utils/helpers';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const DEFAULT_IMG = '/default-avatar.png';

const initialForm = {
  name: '',
  acronym: '',
  tag: '',
  description: '',
  features: '',
  is_active: true,
  order: 0,
};

const AdminSchools = () => {
  const [schools, setSchools] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingSchool, setEditingSchool] = useState(null);
  const [formData, setFormData] = useState(initialForm);
  const [imageFile, setImageFile] = useState(null);
  const fileRef = useRef(null);

  useEffect(() => {
    fetchSchools();
  }, []);

  const fetchSchools = async () => {
    try {
      const res = await api.get('/api/schools/');
      setSchools(res.data);
    } catch (error) {
      toast.error('Failed to load schools');
    } finally {
      setLoading(false);
    }
  };

  const resetForm = () => {
    setEditingSchool(null);
    setFormData(initialForm);
    setImageFile(null);
    if (fileRef.current) fileRef.current.value = '';
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const fd = new FormData();
      fd.append('name', formData.name);
      fd.append('acronym', formData.acronym || '');
      fd.append('tag', formData.tag || '');
      fd.append('description', formData.description || '');
      fd.append('features', formData.features || '');
      fd.append('is_active', String(formData.is_active));
      fd.append('order', String(formData.order));
      if (imageFile) fd.append('image_file', imageFile);

      if (editingSchool) {
        await api.put(`/api/schools/${editingSchool.id}`, fd, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('School updated successfully');
      } else {
        await api.post('/api/schools/', fd, {
          headers: { 'Content-Type': 'multipart/form-data' },
        });
        toast.success('School created successfully');
      }
      setModalOpen(false);
      resetForm();
      fetchSchools();
    } catch (error) {
      console.error(error);
      toast.error(error.response?.data?.detail || 'Operation failed');
    }
  };

  const handleDelete = async (id) => {
    if (!window.confirm('Are you sure you want to delete this school?')) return;
    try {
      await api.delete(`/api/schools/${id}`);
      toast.success('School deleted successfully');
      fetchSchools();
    } catch (error) {
      toast.error('Failed to delete school');
    }
  };

  const handleEdit = (school) => {
    setEditingSchool(school);
    setFormData({
      name: school.name,
      acronym: school.acronym || '',
      tag: school.tag || '',
      description: school.description || '',
      features: school.features || '',
      is_active: school.is_active,
      order: school.order || 0,
    });
    setImageFile(null);
    setModalOpen(true);
  };

  const columns = [
    {
      key: 'image',
      label: 'Image',
      render: (val) => (
        <img
          src={getImageUrl(val, DEFAULT_IMG)}
          alt="school"
          className="w-16 h-12 rounded object-cover"
          onError={(e) => { e.target.src = DEFAULT_IMG; }}
        />
      ),
    },
    {
      key: 'acronym',
      label: 'Acronym',
      render: (val) => <span className="font-semibold text-blue-900">{val || '-'}</span>,
    },
    { key: 'name', label: 'Name' },
    { key: 'tag', label: 'Tag' },
    {
      key: 'is_active',
      label: 'Status',
      render: (val) => (
        <span className={`px-2 py-1 rounded-full text-xs ${val ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'}`}>
          {val ? 'Active' : 'Inactive'}
        </span>
      ),
    },
    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div className="flex space-x-2">
          <button onClick={() => handleEdit(row)} className="text-blue-600 hover:text-blue-800"><FiEdit2 /></button>
          <button onClick={() => handleDelete(row.id)} className="text-red-600 hover:text-red-800"><FiTrash2 /></button>
        </div>
      ),
    },
  ];

  return (
    <div>
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-3xl font-bold text-blue-900">Schools Management</h1>
        <button onClick={() => { resetForm(); setModalOpen(true); }} className="admin-btn-primary flex items-center space-x-2">
          <FiPlus /><span>Add School</span>
        </button>
      </div>

      <AdminCard>
        <AdminTable columns={columns} data={schools} loading={loading} />
      </AdminCard>

      <AdminModal
        isOpen={modalOpen}
        onClose={() => { setModalOpen(false); resetForm(); }}
        title={editingSchool ? 'Edit School' : 'Create School'}
      >
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="admin-label">Name *</label>
                <input type="text" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} className="admin-input" required />
              </div>
              <div>
                <label className="admin-label">Acronym (e.g. NLS)</label>
                <input type="text" value={formData.acronym} onChange={(e) => setFormData({ ...formData, acronym: e.target.value })} className="admin-input" />
              </div>
              <div>
                <label className="admin-label">Tag (e.g. WEG)</label>
                <input type="text" value={formData.tag} onChange={(e) => setFormData({ ...formData, tag: e.target.value })} className="admin-input" />
              </div>
              <div>
                <label className="admin-label">Order</label>
                <input type="number" min="0" value={formData.order} onChange={(e) => setFormData({ ...formData, order: parseInt(e.target.value) || 0 })} className="admin-input" />
              </div>
            </div>
            <div>
              <label className="admin-label">Description</label>
              <textarea value={formData.description} onChange={(e) => setFormData({ ...formData, description: e.target.value })} className="admin-input" rows="3" />
            </div>
            <div>
              <label className="admin-label">Features (comma separated)</label>
              <input type="text" value={formData.features} onChange={(e) => setFormData({ ...formData, features: e.target.value })} className="admin-input" placeholder="Modern Classrooms, STEM Programs, Sports" />
            </div>
            <div>
              <label className="admin-label">Image</label>
              <div className="border-2 border-dashed border-gray-300 rounded-lg p-4 text-center hover:border-blue-900 transition cursor-pointer bg-gray-50/50" onClick={() => fileRef.current?.click()}>
                <input ref={fileRef} type="file" accept="image/jpeg,image/png,image/webp" onChange={(e) => setImageFile(e.target.files?.[0] || null)} style={{ display: 'none' }} />
                {imageFile ? (
                  <p className="text-sm text-blue-900 font-medium">{imageFile.name}</p>
                ) : (
                  <>
                    <div className="text-3xl mb-2">📷</div>
                    <p className="text-sm text-gray-500 font-medium">Click to upload school image</p>
                    <p className="text-xs text-gray-400 mt-1">JPG, PNG, WEBP allowed</p>
                    {editingSchool && editingSchool.image && (
                      <p className="text-xs text-blue-500 mt-2">Current image kept if no new file</p>
                    )}
                  </>
                )}
              </div>
            </div>
            <label className="flex items-center space-x-2">
              <input type="checkbox" checked={formData.is_active} onChange={(e) => setFormData({ ...formData, is_active: e.target.checked })} />
              <span>Active</span>
            </label>
          </div>
          <div className="mt-6 flex justify-end space-x-3">
            <button type="button" onClick={() => { setModalOpen(false); resetForm(); }} className="admin-btn-secondary">Cancel</button>
            <button type="submit" className="admin-btn-primary">{editingSchool ? 'Update' : 'Create'}</button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminSchools;
